CREATE TABLE applicants (
  applicant_id NUMBER PRIMARY KEY,
  name         VARCHAR2(30),
  skills       VARCHAR2(200)
);

INSERT INTO applicants VALUES (1, 'Asha',  'SQL,PL/SQL,Unix');
INSERT INTO applicants VALUES (2, 'Ravi',  'Java, Python');
INSERT INTO applicants VALUES (3, 'Meena', 'Oracle,,AWS');
INSERT INTO applicants VALUES (4, 'Kiran', NULL);
COMMIT;

SET SERVEROUTPUT ON

DECLARE
  l_skills apex_t_varchar2;
BEGIN
  l_skills := apex_string.split('SQL,PL/SQL,Unix', ',');
  FOR i IN 1 .. l_skills.COUNT LOOP
    DBMS_OUTPUT.PUT_LINE(i || ': ' || l_skills(i));
  END LOOP;
END;
/
